#ifndef STATS_H
#define STATS_H

#include <stddef.h>

double mean(const double *values, size_t n);
double maximum(const double *values, size_t n);

#endif /* STATS_H */

#include "stats.h"

double mean(const double *values, size_t n)
{
    double total = 0.0;
    for (size_t i = 0; i < n; i++) {
        total += values[i];
    }
    return n > 0 ? total / n : 0.0;
}

double maximum(const double *values, size_t n)
{
    double best = values[0];
    for (size_t i = 1; i < n; i++) {
        if (values[i] > best) best = values[i];
    }
    return best;
}

#include <stdio.h>
#include "stats.h"

int main(void)
{
    double temps[] = {21.5, 19.0, 24.5, 22.0};
    size_t n = sizeof temps / sizeof temps[0];

    printf("mean = %.2f\n", mean(temps, n));
    printf("max  = %.1f\n", maximum(temps, n));
    return 0;
}

