#ifndef COUNTER_H
#define COUNTER_H
extern int total_calls;      /* declaration: defined in counter.c */
void record_call(void);
#endif

/* counter.c */
#include <stdio.h>
#include "counter.h"

int total_calls = 0;         /* the one definition */

static void log_call(void)   /* private to this file */
{
    printf("call %d\n", total_calls);
}

void record_call(void)
{
    total_calls++;
    log_call();
}

#include <stdio.h>
#include "counter.h"

int main(void)
{
    record_call();
    record_call();
    printf("total: %d\n", total_calls);
    return 0;
}
